// Example: StyledLabel widget test
testWidgets('StyledLabel renders with correct text', (WidgetTester tester) async {
  await tester.pumpWidget(MaterialApp(home: StyledLabel(text: 'Hello')));
  expect(find.text('Hello'), findsOneWidget);
  Text textWidget = tester.widget(find.text('Hello'));
  expect(textWidget.style?.color, Colors.black);
}

