// Example: ActionButton test
testWidgets('ActionButton calls onPressed when tapped', (tester) async {
  bool pressed = false;
  await tester.pumpWidget(MaterialApp(
    home: ActionButton(
      label: 'Tap', 
      onPressed: () => pressed = true
    )
  ));
  await tester.tap(find.byType(ElevatedButton));
  await tester.pump();
  expect(pressed, isTrue);
}

