// Example: Counter widget test
testWidgets('MyCounter increments count', (tester) async {
  await tester.pumpWidget(MaterialApp(home: MyCounter()));
  expect(find.text('Count: 0'), findsOneWidget);
  await tester.tap(find.byKey(Key('increment-btn')));
  await tester.pump();
  expect(find.text('Count: 1'), findsOneWidget);
}

